import {reportScore, storyFeedbackForm} from './quality.js';
import {evidenceGroups, expandEvidence} from './evidence.js';
const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const e = value => String(value ?? '').replace(/[&<>"']/g, s => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const icons = {
 arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>', back:'<path d="m14 6-6 6 6 6"/>', plus:'<path d="M12 5v14M5 12h14"/>',
 file:'<path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6"/>', search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
 map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zm6-2v16m6-14v16"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
 check:'<path d="m5 12 4 4L19 6"/>', chat:'<path d="M4 4h16v12H9l-5 4z"/>', book:'<path d="M12 5C9 3 5 3 2 4v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1zm0 0v15"/>',
 pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>', image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',
 bag:'<path d="M5 7h14l1 14H4zM9 7V5a3 3 0 0 1 6 0v2"/>', link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',
 people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4m2-17a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v3"/>', refresh:'<path d="M20 8a8 8 0 1 0 0 9M20 3v6h-6"/>',
 telegram:'<path d="m3 11 17-7-4 16-5-5-3 3v-5zM8 13 20 4"/>'
};
const icon = name => `<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24">${icons[name]||icons.file}</svg></span>`;
const state = {user:null, providers:{telegram:false}, cases:[], attempt:null, case:null, target:'', journal:'evidence', evidenceFilter:'all', evidenceSearch:'', filter:'all', timer:null, routeToken:0, working:false};
const diff = {easy:'Лёгкое',medium:'Среднее',hard:'Сложное'};
const duration = {short:'30–50 мин',standard:'60–100 мин',long:'2–3 часа'};
const emotions = {calm:'Спокойствие',warm:'Доброжелательность',guarded:'Настороженность',anxious:'Тревога',irritated:'Раздражение',sad:'Печаль',surprised:'Удивление'};
const kindNames = {observation:'Наблюдение',statement:'Показание',item:'Предмет',note:'Заметка',hypothesis:'Гипотеза',link:'Связь',suspect:'О подозреваемом'};
const errorMessage = code => ({provider_429:'Провайдер ограничил частоту запросов. Изображение можно повторить позднее.',quota:'Провайдер сообщил об исчерпании квоты. Прогресс сохранён. После пополнения API-квоты можно повторить операцию.',budget_limit:'Достигнут серверный бюджет AI-операций. Прогресс сохранён; администратор может увеличить бюджет.',provider_401:'Провайдер отклонил API-ключ. Нужна проверка конфигурации сервера.',provider_403:'У провайдера нет доступа к этой операции.',provider_connection_unknown:'Не удалось получить ответ провайдера. Прогресс сохранён. Повтор внешнего запроса иногда может оплачиваться заново.',invalid_content:'Результат генерации не прошёл проверку согласованности. Можно повторить этот этап.',version_conflict:'Мир изменился в другой вкладке. Обновите расследование перед новым действием.',internal_error:'Операция остановилась из-за ошибки. Состояние сохранено, доступен повтор.'}[code] || 'Не удалось завершить операцию. Прогресс сохранён; повторите её позже.');

async function api(path, options={}) {
 const headers = {'Content-Type':'application/json','X-Requested-With':'detective',...options.headers};
 let response;
 try { response=await fetch('/api'+path,{credentials:'same-origin',...options,headers}); }
 catch {throw new Error('Нет связи с сервером. Запрос сохранён — попробуйте повторить после восстановления соединения.');}
 const data=await response.json().catch(()=>({detail:response.status>=500?'Сервер временно недоступен. Ваш прогресс сохранён; повторите запрос.':'Сервер вернул непонятный ответ.'}));
 if(!response.ok){const message=typeof data.detail==='string'?data.detail:response.status===422?'Проверьте поля формы и доступность выбранных доказательств.':'Не удалось выполнить запрос.';const err=new Error(message);err.status=response.status;throw err;}
 return data;
}
const post = (path, body={}, id) => api(path,{method:'POST',body:JSON.stringify(body),headers:id?{'Idempotency-Key':id}:{}});
const freshKey=()=>crypto.randomUUID();
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
function go(path){if(location.hash==='#'+path)route();else location.hash=path;}
function footer(){return `<footer class="footer"><span>ВЕРСИЯ · Бюро самостоятельных расследований</span><span>Правда одна. Путь к ней — ваш.</span></footer>`;}
function header(active=''){const initial=(state.user?.name||state.user?.email||'?')[0].toUpperCase();return `<header class="topbar"><a class="brand" href="#/"><img src="/static/mark.svg" alt="">ВЕРСИЯ<span class="brand-sub">БЮРО РАССЛЕДОВАНИЙ</span></a><nav>${state.user?`<a href="#/library" class="${active==='library'?'active':''}">Мои дела</a><a href="#/new" class="desktop ${active==='new'?'active':''}">Новое расследование</a>${state.user.admin?'<a href="#/admin">Операции</a>':''}<button class="btn text" data-action="logout" title="Выйти из аккаунта"><span class="account-dot">${e(initial)}</span><span class="desktop">Выйти</span></button>`:'<a href="#/login">Войти</a><a class="btn primary sm" href="#/register">Начать расследование '+icon('arrow')+'</a>'}</nav></header>`;}
function render(html){$('#app').innerHTML=html;}
function date(ts){return new Date(ts*1000).toLocaleDateString('ru',{day:'numeric',month:'long'});}
function time(minute=0,start=state.attempt?.start_time||'09:00'){let [h,m]=start.split(':').map(Number);let t=(h*60+m+minute)||0;return `${String(Math.floor(t/60)%24).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;}
function assetFor(kind,id,variant='base'){const assets=state.attempt?.assets||[];return assets.find(a=>a.kind===kind&&a.entity_id===id&&a.variant===variant)||assets.find(a=>a.kind===kind&&a.entity_id===id&&a.variant==='base');}
function portrait(n,cls='avatar'){const a=assetFor('person',n.id,n.emotion==='calm'?'base':n.emotion);return `<span class="${cls}" data-portrait="${e(n.id)}">${a?`<img src="/api/assets/${a.id}" alt="${e(n.name)}">`:e(n.name[0])}</span>`;}

function landing(){render(header()+`<main class="container"><section class="hero"><div><span class="eyebrow">Каждое дело — самостоятельная история</span><h1>У каждого события<br>есть своя <em>версия.</em><br>Найдите правду.</h1><p class="lead">Не выбирайте из готовых ответов. Задавайте свои вопросы, проверяйте догадки и восстанавливайте события — в мире, который отвечает на ваши действия.</p><div class="row"><a class="btn primary" href="#/${state.user?'new':'register'}">Открыть первое дело ${icon('arrow')}</a><span class="small muted">Ваше расследование.<br>Ваш собственный путь.</span></div></div><div class="hero-art" aria-label="Иллюстрация: следственное досье и лупа"><div class="paper"></div><div class="paper small-paper"></div><div class="magnify"></div><span class="hero-caption">НАБЛЮДЕНИЕ → ВОПРОС → ВЕРСИЯ</span></div></section><section class="intro-grid"><article><span class="number">01</span><h3>Мир с неизменной правдой</h3><p>Прошлое уже произошло. Ни уверенное обвинение, ни удачная формулировка не меняют фактов.</p></article><article><span class="number">02</span><h3>Разговор без сценария</h3><p>Спрашивайте своими словами. У каждого свидетеля своя память, интересы и причины молчать.</p></article><article><span class="number">03</span><h3>Выводы принадлежат вам</h3><p>Собирайте наблюдения, связывайте улики и объясняйте случившееся. Игра не решает загадку за вас.</p></article></section></main>`+footer());}
function authPage(register){render(header()+`<main class="auth"><span class="eyebrow">Личный архив расследований</span><h1>${register?'Добро пожаловать<br>в бюро.':'С возвращением.'}</h1><p class="muted">${register?'Ваши дела, наблюдения и версии будут сохранены.':'Незавершённые дела ждут вас в архиве.'}</p>${state.providers.telegram?`<a class="btn telegram-login" href="/api/auth/telegram/start">${icon('telegram')} Продолжить с Telegram</a><div class="auth-divider"><span>или по почте</span></div>`:''}<form id="auth-form" data-mode="${register?'register':'login'}" class="stack"><label>Электронная почта<input type="email" name="email" autocomplete="email" placeholder="you@example.com" required></label><label>Пароль<input type="password" name="password" autocomplete="${register?'new-password':'current-password'}" minlength="10" maxlength="128" placeholder="Не менее 10 символов" required></label><div id="form-error" role="alert"></div><button class="btn primary" type="submit">${register?'Создать аккаунт':'Войти в бюро'} ${icon('arrow')}</button></form><a class="toggle" href="#/${register?'login':'register'}">${register?'Уже есть аккаунт? Войти':'Первое дело? Создать аккаунт'}</a><p class="legal-copy">При первом входе через Telegram аккаунт создаётся автоматически. Состояние дела сохраняется на сервере.</p></main>`);}
function caseCard(c,i){const a=c.attempts?.[0];const ready=c.status==='ready';return `<article class="case-card"><a class="card-link" href="#/${ready&&a?'play/'+a.id:'case/'+c.id}"><div class="case-cover">${c.cover?`<img src="/api/assets/${c.cover}" alt="Место расследования" loading="lazy">`:`<div class="file-symbol">${icon('file')}</div>`}<span class="pill ${ready&&a?.status==='active'?'active':''}">${ready?(a?.status==='finished'?'Завершено':'В расследовании'):c.status==='failed'?'Подготовка остановлена':'Готовим дело'}</span><span class="cover-number">${String(i+1).padStart(2,'0')}</span></div><div class="case-body"><span class="eyebrow">${e(diff[c.settings.difficulty])} · ${duration[c.settings.duration]}</span><h3>${e(c.title)}</h3><p>${e(c.subtitle||c.settings.theme.slice(0,150))}</p><div class="case-footer"><span>${date(c.created)}${c.spoiled?' · Разгадка уже открыта':''}</span><span class="row" style="color:var(--green)">${ready?(a?.status==='finished'?'Открыть разбор':'Продолжить'):'Открыть'} ${icon('arrow')}</span></div></div></a></article>`;}
function library(){const filtered=state.cases.filter(c=>state.filter==='all'||state.filter==='active'&&c.attempts[0]?.status!=='finished'||state.filter==='finished'&&c.attempts.some(a=>a.status==='finished'));render(header('library')+`<main class="container"><div class="page-heading row between"><div><span class="eyebrow">Личный архив · ${state.cases.length} дел</span><h1>Ваши расследования</h1><p class="lead">Некоторые ответы начинаются с правильного вопроса.</p></div><a class="btn primary" href="#/new">${icon('plus')} Новое дело</a></div><div class="archive-toolbar"><div class="tabs">${[['all','Все дела'],['active','В процессе'],['finished','Завершённые']].map(([k,v])=>`<button data-action="filter" data-value="${k}" class="${state.filter===k?'active':''}">${v}</button>`).join('')}</div><span class="small muted">${icon('check')} Прогресс сохраняется автоматически</span></div>${filtered.length?`<div class="case-grid">${filtered.map(caseCard).join('')}</div>`:`<div class="empty"><div><span class="eyebrow">Чистая страница</span><h2>${state.cases.length?'Здесь пока нет дел':'Ваше первое дело ещё впереди'}</h2><p>Задайте место и тему. У каждого нового мира будет своя тайна.</p><a href="#/new" class="btn primary">Создать расследование ${icon('arrow')}</a></div></div>`}</main>`+footer());}
const themes = [ ['Музей после закрытия','Современный приморский город. После закрытия небольшого музея исчезает редкая рукопись. Никакой мистики.'],['Полярная станция','Современная полярная станция в последний день перед зимовкой. Кто-то саботировал оборудование.'],['Ночной экспресс','Европа 1930-х. Ночной поезд и исчезновение пассажира перед пересечением границы.'],['Орбитальная колония','Орбитальная научная колония. Повреждён экспериментальный сад. Реалистичные правила космической станции, без магии.'] ];
function newCase(){render(header('new')+`<main class="container"><div class="page-heading"><span class="eyebrow">Новое самостоятельное расследование</span><h1>Где начнётся ваша история?</h1><p class="lead">Выберите обстоятельства. Остальное пока останется тайной.</p></div><div class="new-layout"><form id="case-form"><section class="form-section"><label for="theme">01 / Место и исходная тема</label><textarea id="theme" name="theme" maxlength="1500" minlength="3" required placeholder="Например: небольшой музей в приморском городе. Накануне выставки исчезает редкая рукопись…">${e(themes[0][1])}</textarea><div class="themes">${themes.map(([name],i)=>`<button class="theme-chip" type="button" data-action="theme" data-index="${i}">${name}</button>`).join('')}</div><p class="caption">Любая эпоха и место. По умолчанию — реалистичный мир.</p></section><section class="form-section"><label>02 / Сложность загадки</label><div class="options">${[['easy','Лёгкое','Ясные зацепки и короткие цепочки выводов'],['medium','Среднее','Несколько версий и личные секреты'],['hard','Сложное','Независимые источники и противодействие']].map(([k,t,d])=>`<label class="option"><input type="radio" name="difficulty" value="${k}" ${k==='medium'?'checked':''}><div class="choice"><strong>${t}</strong><small>${d}</small></div></label>`).join('')}</div></section><section class="form-section"><label>03 / Объём расследования</label><div class="options">${[['short','Короткое','30–50 минут'],['standard','Стандартное','60–100 минут'],['long','Большое','2–3 часа']].map(([k,t,d])=>`<label class="option"><input type="radio" name="duration" value="${k}" ${k==='short'?'checked':''}><div class="choice"><strong>${t}</strong><small>${d}</small></div></label>`).join('')}</div><p class="caption">Ориентир, а не таймер. Время прохождения зависит от вашего темпа.</p></section><section class="form-section"><label for="language">Язык дела</label><select id="language" name="language"><option value="ru">Русский</option><option value="en">English</option></select></section><div id="form-error" role="alert"></div><button class="btn primary" type="submit">Подготовить дело ${icon('arrow')}</button></form><aside class="creation-aside"><span class="eyebrow">За закрытой дверью</span>${icon('file')}<h2>Обстоятельства будут созданы<br>до первого вопроса.</h2><p>Участники, мотивы и материальные следы образуют одну историю. Вы исследуете её в своём порядке, а мир отвечает на ваши поступки.</p><div class="rule"></div><div class="stack"><div class="row">${icon('chat')}<span class="small">Свободные вопросы и действия</span></div><div class="row">${icon('book')}<span class="small">Блокнот для собственных версий</span></div><div class="row">${icon('clock')}<span class="small">Мир ждёт, пока вы размышляете</span></div></div><div class="rule"></div><p>Подготовка может занять несколько минут. Страницу можно закрыть — дело останется в вашем архиве.</p></aside></div></main>`+footer());}
function generationPage(c){state.case=c;const failed=c.status==='failed';const stages=c.generation_version>=2?[['outline','Обстоятельства и доказательства'],['world','Места и способы исследования'],['proof','Проверка доступности улик'],['script','Собеседники и начало истории'],['reading','Проверка разгадки по уликам'],['audit','Проверка согласованности'],['ready','Мир готов к расследованию']]:[['writing','Обстоятельства, люди и следы'],['review','Проверка логики и доступности улик'],['ready','Мир готов к расследованию']];const active=stages.findIndex(([key])=>key===c.stage);render(header()+`<main class="loading-page"><span class="eyebrow">Готовим ваше расследование</span>${failed?icon('file'):'<span class="spinner"></span>'}<h1>${failed?'Подготовка приостановлена':'У каждой тайны<br>должна быть основа.'}</h1><p class="lead">${e(c.settings.theme)}</p><div class="progress-steps">${stages.map(([key,title],i)=>`<div class="progress-step ${c.stage===key?'current':i<active?'done':''}"><span class="disc">${i<active?'✓':i+1}</span><span>${title}</span></div>`).join('')}</div>${failed?`<div class="error">${e(errorMessage(c.error))}</div><button class="btn primary" data-action="retry-case" data-id="${c.id}">Повторить подготовку</button>`:`<p class="small muted">Показываем реальные этапы, без вымышленного процента.<br>Иллюстрации будут появляться постепенно и не задержат начало игры.</p>`}<div class="spacer"></div><a class="btn" href="#/library">Вернуться в архив</a></main>`);}
function evidenceTitle(x){return x.kind==='statement'?x.text.slice(0,100)+(x.text.length>100?'…':''):x.title;}
function evidenceOptions(selected=[],onlyPresentable=true){return evidenceGroups(state.attempt?.world.evidence||[]).filter(x=>!onlyPresentable||x.kind!=='item'||state.attempt.world.inventory.includes(x.id)).map(x=>`<label class="check-label"><input type="checkbox" name="evidence" value="${e(x.id)}" ${x.ids.some(id=>selected.includes(id))?'checked':''}><span>${e(evidenceTitle(x))} <span class="muted">· ${kindNames[x.kind]}</span></span></label>`).join('');}
function sourceName(id){let w=state.attempt.world;const evidence=w.evidence.find(e=>e.id===id);return (evidence?evidenceTitle(evidence):'')||w.people.find(n=>n.id===id)?.name||w.notes.find(n=>n.id===id)?.text.slice(0,50)||'Источник';}
function journalEntries(){const w=state.attempt.world;if(state.journal==='notes')return w.notes.length?w.notes.map(n=>`<article class="entry"><span class="entry-kind">${kindNames[n.kind]} · ваша запись</span><p>${e(n.text)}</p>${n.links.length?`<div class="source">${n.links.map(id=>`<button data-action="source" data-id="${e(id)}">↗ ${e(sourceName(id))}</button>`).join('')}</div>`:''}</article>`).join(''):'<p class="blank">Что кажется важным?<br>Запишите версию или связь между наблюдениями. Только вы решаете, что она означает.</p>';
const search=state.evidenceSearch.toLocaleLowerCase();
const entries=evidenceGroups(w.evidence).filter(x=>(state.evidenceFilter==='all'||x.kind===state.evidenceFilter)&&[x.title,x.text,x.source].join(' ').toLocaleLowerCase().includes(search));
if(!entries.length)return '<p class="blank">'+(w.evidence.length?'Нет записей по этому фильтру.':'Здесь появятся наблюдения и показания. Ваши выводы сохраняйте во вкладке «Мои версии».')+'</p>';
const groups=Map.groupBy?Map.groupBy([...entries].reverse(),x=>x.source):entries.reduce((m,x)=>m.set(x.source,[x,...(m.get(x.source)||[])]),new Map());
return [...groups].map(([source,items])=>`<section class="evidence-group"><h3>${e(source)} <span class="muted">${items.length}</span></h3>${items.map(x=>`<details class="entry evidence-entry"><summary><span class="entry-kind">${kindNames[x.kind]}${x.kind==='item'?(w.inventory.includes(x.id)?' · при себе':' · оставлен'):''}</span><strong>${e(evidenceTitle(x))}</strong><span class="entry-preview">${e(x.text.slice(0,125))}${x.text.length>125?'…':''}</span></summary><p>${x.kind==='statement'?'«'+e(x.text)+'»':e(x.text)}</p><div class="source">${e(w.locations.find(l=>l.id===x.location)?.name||'')} · ${time(x.minute)}</div><button data-action="source" data-id="${e(x.id)}">Открыть запись ↗</button></details>`).join('')}</section>`).join('');}
function journalTools(){return state.journal==='evidence'?`<div class="journal-tools"><label class="small">Найти запись<input id="evidence-search" type="search" value="${e(state.evidenceSearch)}" placeholder="Слово, предмет или имя"></label><div class="journal-filters">${[['all','Все'],['observation','Наблюдения'],['statement','Показания'],['item','Предметы']].map(([key,label])=>`<button data-action="evidence-filter" data-value="${key}" aria-pressed="${state.evidenceFilter===key}">${label}</button>`).join('')}</div><p class="small muted">Показания — слова людей, а не установленные факты. Раскройте запись, чтобы прочитать целиком.</p></div>`:'';}
function investigationLog(a){
 const events=[...a.events].reverse();
 const row=(ev,latest=false)=>{const ids=evidenceGroups(a.world.evidence.filter(x=>(ev.evidence_ids||[]).includes(x.id))).map(x=>x.id);const title=ev.intent||(ev.conversation?'Разговор':'Действие');const details=`${ev.messages.map(m=>`<p>${e(m)}</p>`).join('')}${ids.length?`<div class="event-sources"><span class="small muted">В блокноте:</span>${ids.map(id=>`<button data-action="source" data-id="${e(id)}">${e(sourceName(id))} ↗</button>`).join('')}</div>`:''}${ev.conversation?`<button data-action="talk" data-id="${e(ev.conversation)}">Открыть разговор ↗</button>`:''}`;return `<details class="log-entry compact-event" ${latest?'open':''}><summary><span class="time">${time(ev.minute)}${ev.minutes?' · +'+ev.minutes+' мин':''}</span><strong>${e(title)}</strong>${ids.length?`<span class="event-count">Новых записей: ${ids.length}</span>`:''}</summary><div class="event-details">${details}</div></details>`;};
 return `<section class="event-log"><h4>Ход расследования</h4>${events.length?row(events[0],true)+(events.length>1?`<details class="earlier-events"><summary>Предыдущие действия · ${events.length-1}</summary>${events.slice(1).map(ev=>row(ev)).join('')}</details>`:''):'<p class="small muted">Начните с предмета или разговора. Результат последнего действия появится здесь.</p>'}</section>`;
}

function journal(){return `<aside class="journal" id="journal"><div class="journal-tabs"><button class="${state.journal==='evidence'?'active':''}" data-action="journal" data-value="evidence">Блокнот <span class="muted">${evidenceGroups(state.attempt.world.evidence).length}</span></button><button class="${state.journal==='notes'?'active':''}" data-action="journal" data-value="notes">Мои версии</button></div>${journalTools()}<div class="journal-entries">${journalEntries()}</div>${state.journal==='notes'?`<form id="note-form" class="note-form"><select name="kind" aria-label="Тип записи"><option value="note">Заметка</option><option value="hypothesis">Гипотеза</option><option value="link">Связь между сведениями</option><option value="suspect">О подозреваемом</option></select><textarea name="text" required maxlength="5000" placeholder="Что я предполагаю и почему?"></textarea><details class="evidence-select"><summary>Связать с источниками</summary><div class="evidence-options">${evidenceOptions([],false)}${state.attempt.world.people.map(n=>`<label class="check-label"><input type="checkbox" name="evidence" value="${e(n.id)}">${e(n.name)}</label>`).join('')}</div></details><button class="btn sm" type="submit">${icon('plus')} Сохранить запись</button></form>`:''}</aside>`;}
const briefingRoles={witness:'Свидетель',person_of_interest:'В поле внимания',contact:'Участник дела'};
function briefingPage(a){
 state.attempt=a;const b=a.briefing||{introduction:a.introduction,objective:'Восстановите обстоятельства происшествия и обоснуйте свою версию.',known_facts:[],participants:a.world.people};
 render(header()+`<main class="briefing-page"><a class="briefing-back" href="#/library">${icon('back')} К архиву дел</a><div class="briefing-heading"><span class="eyebrow">Вводная дела · ${e(a.start_time)}</span><h1>${e(a.title)}</h1><p>Ознакомьтесь с обстоятельствами. Расследование начинается с того, что уже известно.</p></div><div class="briefing-grid"><div><section class="briefing-story"><span class="eyebrow">Что произошло</span><p>${e(b.introduction)}</p></section>${b.known_facts.length?`<section class="briefing-facts"><h2>Известно к вашему прибытию</h2><ul>${b.known_facts.map(f=>`<li>${e(f)}</li>`).join('')}</ul></section>`:''}<section class="briefing-objective"><span class="eyebrow">Ваша задача</span><h2>Что предстоит выяснить</h2><p>${e(b.objective)}</p></section></div><aside class="briefing-people"><span class="eyebrow">С кем стоит поговорить</span><h2>Известные участники</h2><p class="small muted">Это исходные сведения. Причастность каждого ещё предстоит проверить.</p>${b.participants.map(n=>`<article class="briefing-person"><span class="briefing-initial">${e(n.name[0])}</span><div><span class="entry-kind">${briefingRoles[n.status]||'Участник дела'}</span><h3>${e(n.name)}</h3><small>${e(n.role)}</small><p>${e(n.context||'')}</p></div></article>`).join('')||'<p>Личности участников пока не установлены. Начните с людей на месте происшествия.</p>'}</aside></div><section class="briefing-start"><div><h3>С чего начать</h3><p>Осмотритесь, выберите человека и начните разговор. Наблюдения и показания попадут в блокнот; выводы остаются за вами.</p><p class="small muted">Чтение вводной и истории диалогов не расходует игровое время.</p></div><button class="btn primary" data-action="start-investigation">${a.world.minute?'Вернуться к расследованию':'Начать расследование'} ${icon('arrow')}</button></section><details class="briefing-rules"><summary>Правила мира</summary><p>${e(a.setting_rules)}</p></details></main>`+footer());
}
function draftKey(aid=state.attempt?.id,target=state.target){return 'draft:'+aid+':'+(target||'scene');}
function rememberDraft(){const d=saveDraft();if(d)sessionStorage.setItem(draftKey(),JSON.stringify(d));}
function restoreChannelDraft(){const d=sessionStorage.getItem(draftKey());if(d)restoreDraft(JSON.parse(d));}
function renderChat(a){
 state.attempt=a;const n=a.world.people.find(p=>p.id===state.target);
 if(!n){state.target='';go('/play/'+a.id);return;}
 const conversation=a.world.dialogue.filter(d=>d.person===n.id);
 let queued;try{queued=JSON.parse(localStorage.getItem('pending:'+a.id)||'null');}catch{}
 const pendingText=queued?.payload.kind==='talk'&&queued.payload.target===n.id?queued.payload.text:'';
 render(header()+`<div class="chat-page"><div class="chat-top"><a class="btn sm" href="#/play/${a.id}">${icon('back')} К месту расследования</a><span>${e(a.title)} · ${time(a.world.minute)}</span><button class="btn sm" data-action="intro">Вводная дела</button></div><div class="chat-layout"><aside class="chat-profile">${portrait(n,'chat-portrait')}<span class="eyebrow">Собеседник</span><h1>${e(n.name)}</h1><p>${e(n.role)}</p><span class="pill">${n.here?emotions[n.emotion]:'Сейчас не рядом'}</span><p class="chat-location">${n.here?'Вы разговариваете в локации «'+e(a.world.locations.find(l=>l.id===a.world.location)?.name)+'».':'История разговора сохранена. Найдите собеседника, чтобы продолжить.'}</p><details><summary>Приметы</summary><p>${e(n.appearance)}</p></details><p class="small muted">Слова собеседника — показания. Их можно сопоставлять с наблюдениями.</p></aside><main class="chat-main"><div class="chat-thread" role="log" aria-label="История разговора · ${e(n.name)}" aria-live="polite">${conversation.length?conversation.map(d=>`<article class="chat-turn"><div class="chat-message mine"><span>Вы · ${time(d.minute)}</span><p>${e(d.player)}</p>${d.shown.length?`<div class="chat-shown">Предъявлено: ${d.shown.map(id=>e(sourceName(id))).join(', ')}</div>`:''}</div><div class="chat-message theirs"><span>${e(n.name)}</span><p>${e(d.reply)}</p></div></article>`).join(''):`<div class="chat-empty">${icon('chat')}<h2>${n.here?'Начните разговор':'Разговор ещё не начат'}</h2><p>${n.here?'Спросите о происшествии и других участниках. Пишите своими словами.':'Собеседника сейчас нет рядом. Вернитесь к месту расследования и найдите его.'}</p></div>`}${a.pending&&pendingText?`<div class="chat-message mine"><span>Вы · отправлено</span><p>${e(pendingText)}</p></div>`:''}${a.pending?'<div class="chat-pending" role="status"><span class="spinner"></span> Действие обрабатывается…</div>':''}</div><form class="composer chat-composer" id="action-form"><div class="composer-head"><span>${icon('chat')} Сообщение собеседнику</span></div><details class="evidence-select"><summary>Предъявить предмет или запись <span id="shown-count"></span></summary><div class="evidence-options">${evidenceOptions()||'<span class="muted">Пока нет найденных доказательств.</span>'}</div></details><textarea id="action-text" aria-label="Сообщение собеседнику" name="text" required maxlength="3000" placeholder="Задайте вопрос или обсудите найденное…" ${a.pending||!n.here?'disabled':''}></textarea><div class="composer-foot"><span>${n.here?'Ответ расходует игровое время · Ctrl/⌘ + Enter — отправить':'Разговор продолжится, когда вы снова встретитесь'}</span><button class="btn primary" type="submit" ${a.pending||!n.here?'disabled':''}>${a.pending?'Ожидаем ответ':'Отправить '+icon('arrow')}</button></div></form><div id="command-error" role="alert"></div></main>${journal()}</div></div>`);
 restoreChannelDraft();const thread=$('.chat-thread');thread.scrollTop=thread.scrollHeight;
 if(a.pending)watchCommand(a.pending.id);else{const saved=localStorage.getItem('pending:'+a.id);if(saved)recoverCommand(JSON.parse(saved));}
 if(a.failed_command&&!a.pending)showCommandFailure(a.failed_command);
 schedule(()=>refreshPlay(a.id),5000);
}
function renderPlay(a){const objectId=$('#modal')?.dataset.objectId;renderPlayContent(a);if(objectId){if(a.world.objects.some(o=>o.id===objectId))objectModal(objectId);else closeModal();}}
function renderPlayContent(a){state.attempt=a;if(state.target)return renderChat(a);const w=a.world;const loc=w.locations.find(l=>l.id===w.location);const bg=assetFor('location',loc.id);render(header()+`<div class="play-header"><div><span class="eyebrow">Личное дело · ${a.status==='finished'?'завершено':'расследование'}</span><h2>${e(a.title)}</h2></div><div><div class="row"><button class="btn sm" data-action="history">${icon('file')} История</button><button class="btn sm" data-action="finish">Завершить дело ${icon('arrow')}</button></div><div class="status-bar">${icon('check')} Сохранено · чтение не расходует игровое время</div></div></div><div class="play-layout"><aside class="side-nav"><h4>Места</h4><div class="places">${w.locations.map(l=>`<button class="place-btn ${l.id===w.location?'active':''}" data-action="travel" data-id="${e(l.id)}" ${l.id!==w.location&&!loc.exits.includes(l.id)?'disabled':''}>${icon('pin')}<span>${e(l.name)}<small>${l.id===w.location?'Вы здесь':loc.exits.includes(l.id)?'Переход · '+l.travel_minutes+' мин':'Нет прямого прохода'}</small></span></button>`).join('')}</div><hr><div class="people-side"><h4>Участники</h4>${w.people.map(n=>`<button class="person-mini" data-action="talk" data-id="${e(n.id)}">${portrait(n)}<span>${e(n.name)}<small class="muted" style="display:block;font-size:9px">${n.here?'Рядом':n.last_seen?.left?'Замечен уход':n.last_seen?.location?'Был(а): '+e(w.locations.find(l=>l.id===n.last_seen.location)?.name)+' · '+time(n.last_seen.minute):'Место неизвестно'}</small></span></button>`).join('')}</div><div class="inventory-side"><hr><h4>При себе · ${w.inventory.length}</h4><div class="inventory">${w.inventory.map(id=>`<button data-action="object" data-id="${e(id)}">${e(w.objects.find(o=>o.id===id)?.name||sourceName(id))}</button>`).join('')||'<span class="small muted">Пока ничего</span>'}</div></div></aside><main class="play-main">${a.spoiled?'<div class="notice" style="margin-bottom:15px">Это новая попытка того же дела. Вы уже могли видеть разгадку.</div>':''}<div class="scene">${bg?`<img class="scene-bg" src="/api/assets/${bg.id}" alt="${e(loc.name)}">`:`<div class="scene-wait">${icon('image')}Иллюстрация готовится<small>Текстовая сцена уже доступна для исследования</small></div>`}<div class="scene-shade"></div><div class="scene-top"><span class="pill">${icon('pin')} ${w.visited.indexOf(loc.id)+1} / ${w.locations.length}</span><span class="pill">${icon('clock')} ${time(w.minute)}</span></div><div class="scene-bottom"><h2>${e(loc.name)}</h2><p>${e(loc.description)}</p></div></div><div class="objects-row" aria-label="Видимые предметы">${w.objects.filter(o=>!w.inventory.includes(o.id)).map(o=>{let a=assetFor('object',o.id);return `<button class="object-tile" data-action="object" data-id="${e(o.id)}">${a?`<img src="/api/assets/${a.id}" alt="">`:icon('search')}<span>${e(o.name)}<small>${o.open?'Открыто':o.locked?'Заперто':'Осмотреть'}</small></span></button>`}).join('')||'<span class="small muted">Нет доступных предметов в поле зрения.</span>'}</div><div class="scene-people">${w.people.filter(n=>n.here).map(n=>`<button class="person-card ${state.target===n.id?'selected':''}" data-action="talk" data-id="${e(n.id)}">${portrait(n)}<span><strong>${e(n.name)}</strong><small>${e(n.role)} · ${emotions[n.emotion]}</small></span></button>`).join('')}</div>${w.inventory.length?`<div class="inventory" style="margin:0 0 13px"><span class="small muted">При себе:</span>${w.inventory.map(id=>`<button data-action="object" data-id="${e(id)}">${e(w.objects.find(o=>o.id===id)?.name||sourceName(id))}</button>`).join('')}</div>`:''}<form class="composer" id="action-form"><div class="composer-head"><span>${icon('search')} Ваше действие</span><span>Обычными словами</span></div><textarea id="action-text" aria-label="Действие в сцене" name="text" required maxlength="3000" placeholder="Например: осматриваю замок и проверяю, нет ли следов взлома…" ${a.pending?'disabled':''}></textarea><div class="composer-foot"><span>${a.pending?'Действие обрабатывается. Мир будет сохранён до ответа.':'Проверка расходует игровое время'}</span><button class="btn primary" type="submit" ${a.pending?'disabled':''}>${a.pending?'<span class="spinner"></span> Выполняется':'Действовать '+icon('arrow')}</button></div></form><div class="quick-actions"><button data-action="suggest" data-text="Осматриваю помещение в целом, отмечаю видимые ориентиры.">Осмотреться</button><button data-action="suggest" data-text="Наблюдаю за обстановкой пять минут.">Наблюдать · 5 мин</button><button data-action="intro">Вводная дела</button><button data-action="hint">Нужна подсказка</button></div><div id="command-error" role="alert"></div>${investigationLog(a)}</main>${journal()}</div>`);if(a.pending)watchCommand(a.pending.id);else{const saved=localStorage.getItem('pending:'+a.id);if(saved)recoverCommand(JSON.parse(saved));}if(a.failed_command&&!a.pending)showCommandFailure(a.failed_command);refreshAssetStatus(a);restoreChannelDraft();schedule(()=>refreshPlay(a.id),5000);}
function saveDraft(){const f=$('#action-form');return f?{text:$('#action-text')?.value||'',shown:$$('input[name=evidence]:checked',f).map(i=>i.value),scroll:window.scrollY,journal:$('#journal')?.scrollTop||0}:null;}
function restoreDraft(d){if(!d)return;if($('#action-text'))$('#action-text').value=d.text;d.shown.forEach(id=>{const el=$$('input[name=evidence]',$('#action-form')||document).find(x=>x.value===id);if(el)el.checked=true;});window.scrollTo(0,d.scroll);}
function isPlayView(aid){return location.hash.split('/')[2]===aid&&!!$('#action-form');}
async function refreshPlay(aid){if(!isPlayView(aid))return;const token=state.routeToken;try{const a=await api('/attempts/'+aid);if(token!==state.routeToken||!isPlayView(aid))return;if(a.status==='finished'){state.attempt=a;verdict(a);return;}if(a.version!==state.attempt.version){let d=saveDraft();renderPlay(a);restoreDraft(d);return;}state.attempt.assets=a.assets;state.attempt.asset_jobs=a.asset_jobs;const busyChanged=!!state.attempt.pending!==!!a.pending;state.attempt.pending=a.pending;if(busyChanged&&$('#modal')?.dataset.objectId)objectModal($('#modal').dataset.objectId);const loc=a.world.location;const bg=assetFor('location',loc);if(bg&&!$('.scene-bg')){const img=document.createElement('img');img.className='scene-bg';img.src='/api/assets/'+bg.id;img.alt=a.world.locations.find(l=>l.id===loc)?.name||'';$('.scene')?.prepend(img);$('.scene-wait')?.remove();}a.world.people.forEach(n=>{const item=assetFor('person',n.id,n.emotion==='calm'?'base':n.emotion);if(item)$$(`[data-portrait="${n.id}"]`).forEach(el=>{if(!el.querySelector('img'))el.innerHTML=`<img src="/api/assets/${item.id}" alt="${e(n.name)}">`;});});refreshAssetStatus(a);if(a.pending&&!state.watching)watchCommand(a.pending.id);}catch{}schedule(()=>refreshPlay(aid),5000);}
function schedule(fn,ms=2500){clearTimeout(state.timer);state.timer=setTimeout(fn,ms);}
function modal(content,wide=false){closeModal();const el=document.createElement('div');el.className='drawer-backdrop';el.id='modal';el.innerHTML=`<section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="Детали расследования"><button class="modal-close" data-action="close-modal" aria-label="Закрыть">×</button>${content}</section>`;document.body.append(el);state.lastFocus=document.activeElement;el.querySelector('button,input,textarea')?.focus();}
function closeModal(){$('#modal')?.remove();state.lastFocus?.focus?.();}
function objectModal(id){
 const w=state.attempt.world,o=w.objects.find(o=>o.id===id);if(!o)return;
 const a=assetFor('object',id),held=w.inventory.includes(id),busy=!!state.attempt.pending;
 const action=(kind,label)=>`<button class="btn" data-action="object-action" data-id="${e(id)}" data-kind="${kind}" data-text="${e(label+': '+o.name)}" ${busy?'disabled':''}>${label}</button>`;
 modal(`<span class="eyebrow">${held?'Предмет при себе':'Объект в сцене'}</span><h2>${e(o.name)}</h2>${a?`<img class="object-image" src="/api/assets/${a.id}" alt="${e(o.name)}">`:''}<p>${e(o.surface)}</p><p class="small muted">Сейчас: ${held?'при себе':e(o.position||'в текущей локации')}${o.open?' · открыто':o.locked?' · заперто':o.openable?' · закрыто':''}</p><div class="object-checks"><h3>Что проверить</h3>${(o.checks||[]).map(c=>c.done?`<button class="check-action completed" data-action="source" data-id="${e(c.id)}"><span>${e(c.label)}</span><small>✓ Записано · перечитать</small></button>`:`<button class="check-action" data-action="object-action" data-kind="check" data-id="${e(id)}" data-check="${e(c.id)}" data-text="${e(c.label)}" ${busy?'disabled':''}><span>${e(c.label)}</span><small>${c.minutes} мин ${icon('arrow')}</small></button>`).join('')||'<p class="small muted">Опишите, что хотите выяснить или как использовать предмет.</p>'}${(o.preparation||[]).map(c=>`<div class="notice small"><p>Для проверки «${e(c.label)}» сначала возьмите инструмент:</p>${c.tools.map(t=>`<button class="btn sm" data-action="object" data-id="${e(t.id)}">${e(t.name)}</button>`).join(' ')}</div>`).join('')}<button class="btn primary" data-action="custom-object" data-name="${e(o.name)}">Своё исследование…</button></div><div class="modal-actions">${o.portable&&!held?action('take','Взять с собой · 1 мин'):''}${held?action('put','Оставить здесь · 2 мин'):''}${o.openable?action(o.open?'close':'open',(o.open?'Закрыть':'Открыть')+' · 1 мин'):''}</div><p class="small muted">Чтение карточки и сохранённых записей не расходует время.</p>`);
 $('#modal').dataset.objectId=id;
}

function sourceModal(id){const w=state.attempt.world;const x=w.evidence.find(x=>x.id===id);if(x){modal(`<span class="eyebrow">${kindNames[x.kind]} · ${time(x.minute)}</span><h2>${e(evidenceTitle(x))}</h2><p>${x.kind==='statement'?e(x.source)+' утверждает: «'+e(x.text)+'»':e(x.text)}</p><div class="spacer"></div><p class="small muted">Источник: ${e(x.source)}<br>Место: ${e(w.locations.find(l=>l.id===x.location)?.name)}</p>${x.kind==='statement'?'<div class="notice" style="margin-top:20px">Это запись слов персонажа. Она не является автоматическим подтверждением факта.</div>':''}`);return;}const n=w.people.find(n=>n.id===id);if(n)modal(`<span class="eyebrow">Участник дела</span><h2>${e(n.name)}</h2><p>${e(n.role)}. ${e(n.appearance)}</p>`);}
function finishModal(){modal(`<span class="eyebrow">Последний шаг расследования</span><h2>Ваша версия событий</h2><form id="finish-form" class="finish-form"><p class="small muted">Объясните, что произошло, кто участвовал, каким способом и почему. Формулировка может быть любой — значение имеют смысл и доказательства.</p><label><span class="field-title">Кто, по вашей версии, причастен?</span><select name="suspect"><option value="">Укажу в объяснении</option>${state.attempt.world.people.map(n=>`<option value="${e(n.id)}">${e(n.name)}</option>`).join('')}</select></label><label><span class="field-title">Что произошло и как это подтверждается?</span><textarea name="text" minlength="20" maxlength="3000" required placeholder="Восстановите последовательность событий, способ и мотив. Какие альтернативы вы исключили?"></textarea></label><details class="evidence-select" open><summary>Подтверждающие сведения</summary><div class="evidence-options">${evidenceOptions([],false)||'Пока нет записанных доказательств. Уверенность сама по себе не доказывает версию.'}</div></details><label class="check-label hint-warning"><input type="checkbox" name="confirmed" required><span>Я завершаю эту попытку. После отправки откроется настоящая история дела; продолжить эту попытку будет нельзя.</span></label><div id="finish-error" role="alert"></div><button class="btn rust" type="submit">Завершить и открыть разбор ${icon('arrow')}</button></form>`);}
function verdict(a){state.attempt=a;const v=a.verdict,ev=v.evaluation,t=v.truth;render(header()+`<main class="verdict"><span class="eyebrow">Разбор расследования · ${e(a.title)}</span><span class="pill active">${ev.proved?'Версия подтверждена доказательствами':'Версия не доказана'}</span><h1>${ev.score!=null?'Ваш отчёт — '+e(ev.score)+' из 10':ev.proved?'У каждого следа<br>нашлось объяснение.':'Расследование завершено.<br>Разберём вашу версию.'}</h1><p class="lead">${e(ev.conclusion)}</p><div class="spacer"></div><div class="row" style="flex-wrap:wrap"><button class="btn primary" data-action="replay" data-id="${a.case_id}">${icon('refresh')} Пройти это дело заново</button><a class="btn" href="#/new">Новое дело ${icon('plus')}</a><button class="btn" data-action="history">История попыток</button></div>${reportScore(ev)}<div class="verdict-columns"><div><section class="verdict-block"><span class="eyebrow">Неизменная правда дела</span><h3>Что произошло</h3><p>${e(t.explanation)}</p><div class="spacer"></div><h3>Способ и мотив</h3><p>${e(t.method)}<br><br>${e(t.motive)}</p></section><section class="verdict-block"><h3>Последовательность событий</h3>${t.timeline.map(x=>`<div class="timeline-item">${e(x)}</div>`).join('')}</section><section class="verdict-block"><h3>Личные секреты участников</h3>${t.innocent_secrets.map(x=>`<p>${e(x)}</p>`).join('<br>')}</section></div><div><section class="verdict-block"><span class="eyebrow">Ваше объяснение</span><p>${e(v.explanation)}</p></section>${[['accurate','Что вы восстановили верно'],['unsupported','Что осталось без доказательств'],['mistaken','Где версия расходится с фактами'],['missing','Какие обстоятельства не объяснены'],['evidence_assessment','Как работают доказательства']].map(([k,title])=>(ev[k]||[]).length?`<section class="verdict-block"><h3>${title}</h3><ul>${ev[k].map(x=>`<li>${e(x)}</li>`).join('')}</ul></section>`:'').join('')}<section class="verdict-block"><h3>Последствия ваших действий</h3>${v.consequences.length?v.consequences.map(x=>`<p>${e(x)}</p>`).join('<br>'):'<p>В этой попытке вы не наблюдали необратимых событий, изменивших исход.</p>'}</section></div></div>${storyFeedbackForm(a)}<p class="legal-copy">Повтор начинает новое расследование с теми же исходными обстоятельствами. Старые показания, предметы и память персонажей не переносятся. Вы уже знаете разгадку — новая попытка помечается соответствующим образом.</p></main>`+footer());}
function refreshAssetStatus(a){
 const jobs=a.asset_jobs||[];
 const failed=jobs.find(j=>j.kind==='location'&&j.entity_id===a.world.location&&j.status==='failed');
 if($('.scene-wait'))$('.scene-wait').innerHTML=failed?`${icon('image')}Иллюстрация не загрузилась<small>Расследование продолжается</small><button class="btn sm" data-action="retry-art" data-id="${failed.id}">Повторить изображение</button>`:`${icon('image')}Иллюстрация готовится<small>Можно продолжать расследование</small>`;
 $$('.object-tile').forEach(el=>{const asset=assetFor('object',el.dataset.id);if(asset&&!$('img',el)){const img=document.createElement('img');img.src='/api/assets/'+asset.id;img.alt='';$('.icon',el)?.remove();el.prepend(img);}});
 const names=new Map([...a.world.objects,...a.world.people,...a.world.locations].map(x=>[x.id,x.name]));
 const failedImages=jobs.filter(j=>j.status==='failed'&&names.has(j.entity_id));
 let status=$('#image-recovery');
 if(!status&&failedImages.length){status=document.createElement('details');status.id='image-recovery';status.className='notice small';$('.scene')?.after(status);}
 if(status){if(!failedImages.length)status.remove();else status.innerHTML=`<summary>Не загрузились изображения: ${failedImages.length}</summary><p>Игра сохранена. Каждое изображение можно подготовить повторно.</p>${failedImages.map(j=>`<div class="row between" style="margin-top:8px"><span>${e(names.get(j.entity_id))}${j.variant!=='base'?' · '+e(emotions[j.variant]||j.variant):''}<small>${e(errorMessage(j.error_code))}</small></span><button class="btn sm" data-action="retry-art" data-id="${e(j.id)}">Повторить</button></div>`).join('')}`;}
}

async function history(){const c=await api('/cases/'+state.attempt.case_id);modal(`<span class="eyebrow">История одного дела</span><h2>${e(c.title)}</h2>${c.attempts.map((a,i)=>`<div class="history-item"><span>Попытка ${c.attempts.length-i}<small>${date(a.created)} · ${a.status==='finished'?'Разбор доступен':'В расследовании'}</small></span><a class="btn sm" href="#/play/${a.id}" data-action="close-modal">${a.status==='finished'?'Разбор':'Продолжить'}</a></div>`).join('')}<div class="spacer"></div><button class="btn" data-action="replay" data-id="${c.id}">Начать новую попытку</button>`);}
async function sendCommand(payload){const a=state.attempt;if(a.pending||state.working)return;payload={kind:'action',text:'',target:state.target,evidence:[],suspect:'',confirmed:false,...payload,version:a.version};payload.evidence=expandEvidence(a.world.evidence,payload.evidence);const existing=localStorage.getItem('pending:'+a.id);const saved=existing?JSON.parse(existing):{key:freshKey(),payload,aid:a.id};if(existing&&JSON.stringify(saved.payload)!==JSON.stringify(payload)){toast('Предыдущий запрос ещё не подтверждён. Сначала восстановим его результат.');return recoverCommand(saved);}localStorage.setItem('pending:'+a.id,JSON.stringify(saved));await recoverCommand(saved);}
async function recoverCommand(saved){if(state.working||!state.attempt||state.attempt.id!==saved.aid)return;state.working=true;try{const r=await post('/attempts/'+saved.aid+'/commands',saved.payload,saved.key);state.attempt.pending=r;sessionStorage.removeItem(draftKey(saved.aid,saved.payload.kind==='talk'?saved.payload.target:''));if(state.target===(saved.payload.kind==='talk'?saved.payload.target:''))if($('#action-text'))$('#action-text').value='';closeModal();const a=await api('/attempts/'+saved.aid);renderPlay(a);watchCommand(r.id);}catch(err){if(err.status&&err.status<500)localStorage.removeItem('pending:'+saved.aid);toast(err.message);if($('#command-error'))$('#command-error').innerHTML=`<div class="error">${e(err.message)} ${!err.status?'<button class="btn sm" data-action="recover">Восстановить запрос</button>':''}</div>`;}finally{state.working=false;}}
function showCommandFailure(result){if($('#command-error'))$('#command-error').innerHTML=`<div class="error">${e(errorMessage(result.result?.error))}${result.job_id?`<div class="spacer"></div><button class="btn sm" data-action="retry-command" data-id="${e(result.job_id)}" data-command="${e(result.id)}">Повторить операцию</button>`:''}</div>`;}
async function watchCommand(id){if(state.watching===id)return;state.watching=id;const aid=state.attempt.id;try{let result=await api('/commands/'+id);if(result.status==='done'){localStorage.removeItem('pending:'+aid);state.watching=null;if(state.attempt?.id===aid&&isPlayView(aid)){const a=await api('/attempts/'+aid);if(a.status==='finished')verdict(a);else renderPlay(a);}return;}if(result.status==='failed'){localStorage.removeItem('pending:'+aid);state.watching=null;if(state.attempt?.id===aid&&isPlayView(aid)){const a=await api('/attempts/'+aid);renderPlay(a);showCommandFailure({...result,id});}return;}setTimeout(()=>{state.watching=null;if(state.attempt?.id===aid&&isPlayView(aid))watchCommand(id);},1800);}catch{state.watching=null;setTimeout(()=>{if(state.attempt?.id===aid&&isPlayView(aid))watchCommand(id);},4000);}}
async function adminPage(){const data=await api('/admin/jobs');render(header()+`<main class="container"><span class="eyebrow">Обслуживание</span><div class="page-heading row between"><h1>Операции</h1><button class="btn" data-action="admin-refresh">Обновить</button></div><p class="lead">Повтор восстанавливает отдельный этап. Успешные этапы остаются сохранёнными.</p><div class="spacer"></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Операция</th><th>Статус</th><th>Попытки</th><th>Причина</th><th></th></tr></thead><tbody>${data.jobs.map(j=>`<tr><td>${e(j.kind)}<br><small>${e(j.id.slice(0,10))}</small></td><td>${e(j.status)}</td><td>${j.attempts}</td><td>${e(j.error_code||'—')}<br><small>${e(j.diagnostic||'')}</small></td><td>${j.status==='failed'?`<button class="btn sm" data-action="admin-retry" data-id="${j.id}">Повторить</button>`:''}</td></tr>`).join('')}</tbody></table></div><div class="spacer"></div><h2>Потребление AI</h2><p class="small muted">Реальные вызовы и токены. Денежная стоимость зависит от тарифов провайдера; счётчики не являются счётом.</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Категория</th><th>Модель</th><th>Статус</th><th>Вызовы</th><th>Вход / выход</th><th>Секунд</th></tr></thead><tbody>${data.usage.map(u=>`<tr><td>${e(u.category)}</td><td>${e(u.model)}</td><td>${e(u.status)}</td><td>${u.calls}</td><td>${u.input_tokens||0} / ${u.output_tokens||0}</td><td>${Math.round(u.avg_seconds||0)}</td></tr>`).join('')}</tbody></table></div></main>`);}

async function route(){rememberDraft();window.scrollTo(0,0);clearTimeout(state.timer);closeModal();state.watching=null;const token=++state.routeToken;const path=location.hash.slice(1)||'/';if(!state.user&&!['/','/login','/register'].includes(path)){go('/login');return;}try{if(path==='/')return state.user?(go('/library')):landing();if(path==='/login'||path==='/register')return authPage(path==='/register');if(path==='/new')return newCase();if(path==='/library'){state.cases=await api('/cases');if(token!==state.routeToken)return;library();if(state.cases.some(c=>c.status!=='ready'&&c.status!=='failed'))schedule(route,5000);return;}if(path.startsWith('/case/')){const c=await api('/cases/'+path.split('/')[2]);if(token!==state.routeToken)return;if(c.status==='ready'&&c.attempts.length){go('/play/'+c.attempts[0].id);return;}generationPage(c);if(c.status!=='failed')schedule(route,3000);return;}if(path.startsWith('/play/')){const a=await api('/attempts/'+path.split('/')[2]);if(token!==state.routeToken)return;const parts=path.split('/');state.target=parts[3]==='chat'?parts[4]:'';if(a.status==='finished')verdict(a);else if(parts[3]==='briefing'||!localStorage.getItem('briefing-read:'+a.id))briefingPage(a);else renderPlay(a);return;}if(path==='/admin')return adminPage();go('/library');}catch(err){if(err.status===401){state.user=null;go('/login');return;}render(header()+`<main class="container"><h2>Не удалось открыть страницу</h2><div class="error">${e(err.message)}</div><button class="btn" data-action="reload">Повторить</button></main>`);}}

 document.addEventListener('submit',async event=>{const form=event.target;if(!['auth-form','case-form','action-form','note-form','finish-form','story-feedback-form'].includes(form.id))return;event.preventDefault();const button=$('button[type=submit]',form);if(button?.disabled)return;const fd=new FormData(form);button.disabled=true;try{
 if(form.id==='auth-form'){state.user=await post('/auth/'+form.dataset.mode,{email:fd.get('email'),password:fd.get('password')});go('/library');}
 if(form.id==='case-form'){const settings=Object.fromEntries(fd);const old=JSON.parse(localStorage.getItem('case-request')||'null');const req=old&&JSON.stringify(old.settings)===JSON.stringify(settings)?old:{key:freshKey(),settings};localStorage.setItem('case-request',JSON.stringify(req));const c=await post('/cases',settings,req.key);localStorage.removeItem('case-request');go('/case/'+c.id);}
 if(form.id==='action-form')await sendCommand({kind:state.target?'talk':'action',text:fd.get('text'),evidence:fd.getAll('evidence')});
 if(form.id==='finish-form')await sendCommand({kind:'finish',text:fd.get('text'),evidence:fd.getAll('evidence'),suspect:fd.get('suspect'),confirmed:fd.has('confirmed'),target:''});
 if(form.id==='story-feedback-form'){const body=Object.fromEntries(fd);for(const k of ['fairness','discoveries','agency','characters','pacing'])body[k]=Number(body[k]);state.attempt.story_feedback=await post('/attempts/'+state.attempt.id+'/feedback',body);verdict(state.attempt);toast('Оценка сюжета сохранена.');}
 if(form.id==='note-form'){await post('/attempts/'+state.attempt.id+'/notes',{text:fd.get('text'),kind:fd.get('kind'),links:fd.getAll('evidence'),version:state.attempt.version},form.dataset.key||(form.dataset.key=freshKey()));const d=saveDraft();const a=await api('/attempts/'+state.attempt.id);renderPlay(a);restoreDraft(d);toast('Запись сохранена. Игровое время не изменилось.');}
 }catch(err){let el=$('#form-error',form)||$('#finish-error',form)||$('#command-error');if(el)el.innerHTML=`<div class="error">${e(err.message)}</div>`;else toast(err.message);}finally{if(button?.isConnected)button.disabled=false;}});
 document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(!['close-modal'].includes(action)||el.tagName!=='A')event.preventDefault();try{
 if(action==='retry-connection'){location.reload();return;}
 if(action==='logout'){await post('/logout');state.user=null;go('/');}
 if(action==='filter'){state.filter=el.dataset.value;library();}
 if(action==='theme')$('#theme').value=themes[+el.dataset.index][1];
 if(action==='reload')route();
 if(action==='retry-case'){el.disabled=true;await post('/cases/'+el.dataset.id+'/retry');route();}
 if(action==='object')objectModal(el.dataset.id);
 if(action==='source')sourceModal(el.dataset.id);
 if(action==='close-modal')closeModal();
 if(action==='suggest'){state.target='';const d=saveDraft();renderPlay(state.attempt);restoreDraft(d);$('#action-text').value=el.dataset.text;$('#action-text').focus();}
 if(action==='object-action'){const payload={kind:'object',text:el.dataset.text,target:el.dataset.id,object_action:el.dataset.kind,check_id:el.dataset.check||''};closeModal();await sendCommand(payload);}
 if(action==='custom-object'){const name=el.dataset.name;closeModal();$('#action-text').value='Исследую '+name+': ';$('#action-text').focus();}
 if(action==='talk')go('/play/'+state.attempt.id+'/chat/'+el.dataset.id);
 if(action==='untarget')go('/play/'+state.attempt.id);
 if(action==='travel'){if(el.dataset.id===state.attempt.world.location)return;const l=state.attempt.world.locations.find(l=>l.id===el.dataset.id);await sendCommand({kind:'travel',text:'Перехожу в локацию «'+l.name+'».',target:l.id});}
 if(action==='evidence-filter'){state.evidenceFilter=el.dataset.value;$('.journal-entries').innerHTML=journalEntries();$('.journal-tools').outerHTML=journalTools();}
 if(action==='journal'){const d=saveDraft();state.journal=el.dataset.value;renderPlay(state.attempt);restoreDraft(d);}
 if(action==='intro')go('/play/'+state.attempt.id+'/briefing');
 if(action==='start-investigation'){localStorage.setItem('briefing-read:'+state.attempt.id,'1');go('/play/'+state.attempt.id);}
 if(action==='finish')finishModal();
 if(action==='history')await history();
 if(action==='replay'){const cid=el.dataset.id;modal(`<span class="eyebrow">Новая попытка того же дела</span><h2>Вернуться к началу?</h2><p>Правда о произошедшем останется прежней. Предметы, знания персонажей и блокнот начнут с исходного состояния. История предыдущих попыток сохранится.</p><div class="modal-actions"><button class="btn primary" data-action="confirm-replay" data-id="${cid}">Начать заново</button><button class="btn" data-action="close-modal">Остаться</button></div>`);}
 if(action==='confirm-replay'){el.disabled=true;const storageKey='replay:'+el.dataset.id;const k=localStorage.getItem(storageKey)||freshKey();localStorage.setItem(storageKey,k);const a=await post('/cases/'+el.dataset.id+'/replay',{},k);localStorage.removeItem(storageKey);closeModal();go('/play/'+a.id);}
 if(action==='hint')modal(`<span class="eyebrow">Помощь по вашему запросу</span><h2>${state.attempt.world.hints?'Ещё одно направление?':'Нужен свежий взгляд?'}</h2><p>Подсказка направит внимание на возможную проверку. Следующие подсказки становятся конкретнее. Это не оценка вашей версии; виновник не будет назван.</p><div class="modal-actions"><button class="btn primary" data-action="confirm-hint">Получить подсказку</button><button class="btn" data-action="close-modal">Продолжить самостоятельно</button></div>`);
 if(action==='confirm-hint'){closeModal();await sendCommand({kind:'hint',target:''});}
 if(action==='recover'){const s=localStorage.getItem('pending:'+state.attempt.id);if(s)await recoverCommand(JSON.parse(s));}
 if(action==='retry-command'){el.disabled=true;await post('/jobs/'+el.dataset.id+'/retry');watchCommand(el.dataset.command);}
 if(action==='retry-art'){el.disabled=true;await post('/jobs/'+el.dataset.id+'/retry');state.attempt.asset_jobs?.forEach(j=>{if(j.id===el.dataset.id)j.status='queued';});refreshAssetStatus(state.attempt);toast('Изображение поставлено на повторную подготовку.');}
 if(action==='admin-refresh')await adminPage();
 if(action==='admin-retry'){el.disabled=true;await post('/admin/jobs/'+el.dataset.id+'/retry');await adminPage();}
 }catch(err){toast(err.message);if(el.isConnected)el.disabled=false;}});
 document.addEventListener('change',event=>{if(event.target.name==='evidence'&&$('#shown-count')){const checked=$$('input[name=evidence]:checked',$('#action-form'));$('#shown-count').textContent=checked.length?'· выбрано '+checked.length:'';}});
 document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key==='Tab'&&$('#modal')){const els=$$('button,a,input,textarea,select,summary',$('#modal')).filter(x=>!x.disabled);const first=els[0],last=els.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}if((event.ctrlKey||event.metaKey)&&event.key==='Enter'&&document.activeElement===$('#action-text'))$('#action-form')?.requestSubmit();});
 window.addEventListener('hashchange',()=>{window.scrollTo(0,0);route();});
 let startupError=null;
 try{state.providers=await api('/auth/providers');}catch{}
 try{state.user=await api('/me');}catch(err){if(err.status!==401){render(header()+`<main class="container"><h2>Не удалось восстановить соединение</h2><div class="error">${e(err.message)}</div><button class="btn" data-action="retry-connection">Повторить подключение</button></main>`);startupError=err;}}
 const telegramError=new URLSearchParams(location.search).get('telegram_error');
 if(telegramError){
  const messages={cancelled:'Вход через Telegram отменён.',state:'Сессия входа устарела. Попробуйте ещё раз.',response:'Telegram не вернул код входа. Попробуйте ещё раз.',verification:'Не удалось подтвердить вход через Telegram. Попробуйте ещё раз.'};
  toast(messages[telegramError]||'Не удалось войти через Telegram.');
  history.replaceState(null,'',location.pathname+location.hash);
 }
 if(!startupError)route();

document.addEventListener('input',event=>{if(event.target.closest('#action-form'))rememberDraft();});
document.addEventListener('change',event=>{if(event.target.closest('#action-form'))rememberDraft();});

document.addEventListener('input',event=>{if(event.target.id==='evidence-search'){state.evidenceSearch=event.target.value;$('.journal-entries').innerHTML=journalEntries();}});
